"""연희동 땅: 캠퍼스 서쪽 · 북서쪽 동네(연희동, 서울외국인학교 서쪽 반)를 측량 표고로 (#189;
reference/고증/4.12_대운동장.md 「연희동 땅」, 4.8.3, 2.8.1).  tools/build_campus.py 가 부른다.

    info = yeonhui97.far_edge(Hf, half, step)         # 먼 지형의 서 · 북쪽 가장자리 마디: 측량 면으로(town97.far_ring 바로 뒤)
    info = yeonhui97.lay(Hn, X, Y, far, keep, fill)   # 심기가 끝난 뒤, town97.lay 바로 뒤(철둑 · 성산로를 놓기 앞)
    n = yeonhui97.rebase(buildings, ground)           # 땅 고르기가 모두 끝난 뒤: 동네 집의 바닥을 새 땅에

Frame: campus metres, x east, y north.

- The game's ground west and north-west of the campus was the base terrain (the surface model with its buildings
  opened away, 2.8), which still stood 3 - 9 m over the 1:5000 survey of 2006 across 연희동 (+4.1 m in the middle:
  the houses' roofs and the trees in it), and 5 - 13 m under it on the hill of 서울외국인학교's west half (the halls taken
  out of the model cut the hill with them).
- GRID: the ground above sea level (해발, decimetres) every 10 m, x -810 .. -150, y -200 .. 810.  It is the 1:5000
  survey of 2006 (국토지리정보원 수치지형도 「서울078」, the later edition of the two, 고증 1.5) made as tools/town97.py's
  GRID was: the 5 and 25 m contours filled in between (harmonic, 2.5 m), then the residuals of all
  the edition's spot heights in the box (142) spread by a thin-plate spline (smoothing 5).  Unlike the town's, no spot
  is left out for being off its neighbours: here those are real hill tops and the low ground towards 홍제천 (the 2024
  edition has the same heights at the same places), not bridges.  Against the 2024 edition's spots inside REGION
  (86, a survey of its own): surface - spot -0.17 m in the middle, 16 - 84 % -1.41 .. +0.28; against the
  1997-07-28 scans (26/14 · 26/15 · 26/16, 15 m lattice, pairs agreeing within 0.6 m, correlation 0.7 and over: 1,108
  points in REGION, most of them roofs) the lowest mode of photo - surface, the ground's, at 0 .. +0.5 (median +0.28),
  the leaf-off ones of 1996-12-23 at +0.5 .. +1.0.  The 10 m table against the 2.5 m surface: rms 0.23 m.
- REGION: west of the campus.  Its campus side runs (south to north) from the road north-west of 성산로's end
  (tools/west_ground.py field_sw lays its bed afterwards) along west of the spur north of 학군단 (tools/fieldhill97.py
  SPUR · BOWL), the hill's north edge (HILL), the campus wall either side of 서문, west of the valley north-west of
  과학관 (x -380 by the gate's houses, where tools/west_ground.py valley and tools/seomun.py have the 1997 photos'
  ground; x -362 north of y 110, so that the valley's VALLEY_KEEP points at x -374 read this ground and not the
  surface model's 6 - 11 m over it), north of the valley's floor (y 205, the scans' points end at y 202) to the
  ridge's west edge (x -295), the ridge's north edge (tools/ridge97.py RIDGE, y 262), west of the wood
  north-west of the halls (tools/jonghap97.py HILL, x -205, y 400 - 425) and on north along x -160 through
  서울외국인학교 (its east half, where the game is mostly within 2 m of the survey, 3.3 m at most, stays); south
  it overlaps the town's (tools/town97.py: its weight fades out west of x -600 between y -180 and -110).  The blocks
  laid after this one on their own data (the road's bed, 서문, the hill, the spur, the valley, the ridge, the wood)
  ease into it themselves.
- lay(): the nodes in REGION (not `keep`) take GRID (+ T); round its campus side, out to RING m, the ground is
  smoothed (fill: harmonic) between it and the ground that stays; over RIM m at the near grid's outer edges (x -800,
  y 800) the ground eases into the far terrain's edge (straight between its 100 m nodes, as the web draws the far
  ring), whose nodes there far_edge() has put on GRID first: the relief between them fades in, as tools/town97.py does.
- rebase(): OSM's houses ('city') inside REGION stood on the old ground (their floors read it before any of this):
  their floor and top_ground go to the new ground's lowest and highest corner.
- The build's working datum is 해발 + T (tools/datum.py tilt); surf() adds it.  Nothing here draws from any random
  stream; the trees, shrubs and cars in REGION stand on whatever ground is under them (the web reads it).  The far
  terrain's forest and city decide on its heights as they were (campus.json terrain.far.rng, tools/build_campus.py).
"""
import numpy as np
import shapely
from scipy import ndimage
from shapely.geometry import LineString, Polygon

import datum

GRID_X0, GRID_Y0, GRID_D = -810.0, -200.0, 10.0
RING, RIM = 12.0, 60.0
# the campus side, south to north (see the head); then the near grid's north and west edges and the seam with the town
SIDE = [(-600.0, -185.0), (-560.0, -200.0), (-548.0, -170.0), (-545.0, -145.0), (-536.0, -122.0), (-515.0, -106.0),
        (-502.0, -104.0), (-501.0, -97.0), (-493.0, -89.0), (-483.0, -83.0), (-472.0, -76.0), (-462.0, -69.0),
        (-450.0, -64.0), (-435.0, -59.0), (-420.0, -58.0), (-405.0, -62.0), (-397.0, -66.0), (-388.0, -68.0),
        (-380.0, -70.0), (-374.0, -76.0), (-378.0, -50.0), (-375.4, -48.7), (-361.7, -20.3), (-361.6, -15.2),
        (-359.5, -4.0), (-357.0, 11.0), (-378.0, 25.0), (-380.0, 95.0), (-362.0, 110.0), (-362.0, 205.0),
        (-295.0, 205.0), (-295.0, 262.0), (-205.0, 270.0), (-205.0, 400.0), (-150.0, 400.0), (-150.0, 425.0),
        (-160.0, 425.0), (-160.0, 805.0)]
REGION = Polygon(SIDE + [(-805.0, 805.0), (-805.0, -185.0)])
# the far terrain's nodes (100 m) on the near grid's edges along REGION: the west edge and the north edge
OUTER = [(-800.0, float(y)) for y in range(-100, 801, 100)] + [(float(x), 800.0) for x in range(-700, -199, 100)]
GRID = None


def _grid():
    global GRID
    if GRID is None:
        GRID = np.array([[int(v) for v in r.split()] for r in _GRID.strip().split('\n')], float) / 10.0
    return GRID


def _smooth(t):
    t = np.clip(t, 0.0, 1.0)
    return t * t * (3 - 2 * t)


def sea(x, y):
    """the ground above sea level (해발) at (x, y): GRID, bilinear.  Arrays are accepted"""
    xa, ya = np.broadcast_arrays(np.asarray(x, float), np.asarray(y, float))
    r = ndimage.map_coordinates(_grid(), [(ya.ravel() - GRID_Y0) / GRID_D, (xa.ravel() - GRID_X0) / GRID_D], order=1,
                                mode='nearest').reshape(xa.shape)
    return float(r) if r.ndim == 0 else r


def surf(x, y):
    """... on the working datum (해발 + tilt)"""
    return sea(x, y) + datum.tilt(x, y)


def _rim(X, Y):
    """0 at the near grid's west and north edges, 1 from RIM m inside them"""
    xa, ya = np.asarray(X, float), np.asarray(Y, float)
    return _smooth(np.minimum(xa + 800.0, 800.0 - ya) / RIM)


def _node(half, step, x, y):
    return int(round((y + half) / step)), int(round((x + half) / step))


def far_edge(Hf, half, step):
    """The far terrain's nodes on OUTER onto GRID (Hf: the far ring on the working datum, rows south -> north, in
    place).  Returns a summary"""
    d = []
    for x_, y_ in OUTER:
        j_, i_ = _node(half, step, x_, y_)
        z = surf(x_, y_)
        d.append(z - Hf[j_, i_])
        Hf[j_, i_] = z
    d = np.array(d)
    return dict(nodes=len(OUTER), median=round(float(np.median(d)), 2), low=round(float(d.min()), 1), high=round(float(d.max()), 1))


def _edge_z(X, Y, far):
    """the far terrain's edge (straight between OUTER's nodes, as the web draws the far ring) at the nearest point of
    the near grid's west or north edge to each (X, Y), less the surface there"""
    Hf, half, step = far
    xa, ya = np.ravel(np.asarray(X, float)), np.ravel(np.asarray(Y, float))
    west = (xa + 800.0) <= (800.0 - ya)
    ex = np.where(west, -800.0, np.clip(xa, -800.0, -200.0))
    ey = np.where(west, np.clip(ya, -100.0, 800.0), 800.0)
    t = np.where(west, (ey + half) / step, (ex + half) / step)
    k0 = np.floor(t).astype(int)
    k1 = np.minimum(k0 + 1, Hf.shape[0] - 1)
    f = t - k0
    i_w = _node(half, step, -800.0, 0.0)[1]          # (the west edge's column)
    j_n = _node(half, step, 0.0, 800.0)[0]           # (the north edge's row)
    a = np.where(west, Hf[k0, i_w], Hf[j_n, k0])
    b = np.where(west, Hf[k1, i_w], Hf[j_n, k1])
    return (a * (1 - f) + b * f - surf(ex, ey)).reshape(np.shape(X))


def lay(Hn, X, Y, far, keep, fill):
    """The near grid's nodes in REGION (not keep) onto GRID, eased into the far terrain's edge over RIM (far: (Hf, half,
    step) after far_edge()); round REGION's campus side out to RING m smoothed (fill: harmonic_fill, on Hn).  Returns
    the nodes set and a summary"""
    H0 = Hn.copy()
    core = shapely.contains_xy(REGION, X, Y) & ~keep
    t = surf(X[core], Y[core])
    w = _rim(X[core], Y[core])
    e = w < 0.999
    if e.any():
        t[e] = t[e] + _edge_z(X[core][e], Y[core][e], far) * (1.0 - w[e])
    Hn[core] = t
    side = LineString(SIDE)
    near_side = (np.abs(X - (-360.0)) < 460.0) & (Y > -215.0) & (Y < 818.0)
    free = np.zeros(X.shape, bool)
    free[near_side] = shapely.distance(shapely.points(np.stack([X[near_side], Y[near_side]], 1)), side) <= RING
    free &= ~shapely.contains_xy(REGION, X, Y) & ~keep
    if free.any():
        fill(free)
    d = Hn - H0
    full = core & (_rim(X, Y) > 0.999)
    return core | free, dict(nodes=int(core.sum()), eased=int(free.sum()), median=round(float(np.median(d[full])), 2),
                             p16=round(float(np.percentile(d[full], 16)), 2), p84=round(float(np.percentile(d[full], 84)), 2),
                             low=round(float(d.min()), 1), high=round(float(d.max()), 1))


def rebase(buildings, ground):
    """OSM's houses ('city', not the town's or 서문's own) inside REGION: base and top_ground on the ground as it now is
    (ground: x, y -> the working datum).  Returns how many moved and by how much (median, low, high)"""
    moved = []
    for b in buildings:
        if b.get('style') != 'city' or 900000 <= b['id'] < 1000000:      # (the game's own houses: 서문's, the town's)
            continue
        fp = b['footprint']
        cx, cy = np.mean([p[0] for p in fp]), np.mean([p[1] for p in fp])
        if not REGION.contains(shapely.geometry.Point(cx, cy)):
            continue
        hs = [float(ground(x_, y_)) for x_, y_ in fp]
        moved.append(min(hs) - b['base'])
        b.update(base=round(min(hs), 2), top_ground=round(max(hs), 2))
    m = np.array(moved) if moved else np.zeros(1)
    return dict(houses=len(moved), median=round(float(np.median(m)), 2), low=round(float(m.min()), 1), high=round(float(m.max()), 1))


